import datetime
import calendar
from decimal import Decimal

_UTC = datetime.timezone.utc


def _localize(naive, tz):
    # PostgreSQL rules for local wall time -> timestamptz:
    # ambiguous (fall-back) -> offset after transition (standard, fold=1)
    # nonexistent (spring-forward gap) -> offset before transition (fold=0)
    d1 = naive.replace(tzinfo=tz, fold=1)
    back = d1.astimezone(_UTC).astimezone(tz).replace(tzinfo=None)
    if back == naive:
        chosen = d1
    else:
        chosen = naive.replace(tzinfo=tz, fold=0)
    return chosen.astimezone(_UTC).astimezone(tz)


def _local_naive(ts, tz):
    return ts.astimezone(tz).replace(tzinfo=None)


def _trunc_day(ts, tz):
    # adempiere.trunc(timestamptz): CAST(x AS date) in the session zone, then date -> timestamptz
    if ts is None:
        return None
    loc = _local_naive(ts, tz)
    return _localize(datetime.datetime(loc.year, loc.month, loc.day), tz)


def _trunc_month(ts, tz):
    # adempiere.trunc(timestamptz, 'MM') -> date, assigned to a timestamptz variable
    if ts is None:
        return None
    loc = _local_naive(ts, tz)
    return _localize(datetime.datetime(loc.year, loc.month, 1), tz)


def _adddays(ts, days, tz):
    # adempiere.adddays: ts + interval '1 second' * (86400 * days), elapsed time
    if ts is None or days is None:
        return None
    secs = float(Decimal(86400) * days)
    us = round(1000000.0 * secs)
    res = ts.astimezone(_UTC) + datetime.timedelta(microseconds=us)
    return res.astimezone(tz)


def _add_months(ts, months, tz):
    # adempiere.add_months: ts + interval '1 month' * trunc(months), in local wall-clock fields
    if ts is None or months is None:
        return None
    n = int(months)  # truncation toward zero
    loc = _local_naive(ts, tz)
    total = loc.year * 12 + (loc.month - 1) + n
    y = total // 12
    m = total % 12 + 1
    last = calendar.monthrange(y, m)[1]
    d = loc.day if loc.day <= last else last
    naive = loc.replace(year=y, month=m, day=d)
    return _localize(naive, tz)


def paymenttermduedate(paymentterm_id, docdate, *, data):
    tz = data.session_tz
    due = _trunc_day(docdate, tz)
    rows = data.select("c_paymentterm", c_paymentterm_id=paymentterm_id)
    for p in rows:
        if p.get("isduefixed") == "Y":
            first_day = _trunc_month(docdate, tz)
            trunc_doc = _trunc_day(docdate, tz)
            if first_day is None or trunc_doc is None:
                no_days = None
            else:
                diff = trunc_doc.astimezone(_UTC) - first_day.astimezone(_UTC)
                diff_us = (diff.days * 86400 + diff.seconds) * 1000000 + diff.microseconds
                q = abs(diff_us) // 86400000000
                no_days = Decimal(q if diff_us >= 0 else -q)
            fmd = p.get("fixmonthday")
            due = _adddays(first_day, None if fmd is None else fmd - 1, tz)
            due = _add_months(due, p.get("fixmonthoffset"), tz)
            cutoff = p.get("fixmonthcutoff")
            if no_days is not None and cutoff is not None and no_days > cutoff:
                due = _add_months(due, Decimal(1), tz)
        else:
            due = _adddays(_trunc_day(docdate, tz), p.get("netdays"), tz)
    if due is None:
        return None
    return due.astimezone(tz)
